package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import java.util.regex.*;
/** Equal-group decimal quantities, derived only from the visible original quantity and count. */
public final class DecimalMeasureGroups {
 private DecimalMeasureGroups(){}
 public static final String MUL="decimalQuantityGroups",DIV="decimalQuantitySharing";
 public static final List<Catalog.Skill> SKILLS=List.of(new Catalog.Skill(MUL,"소수로 나타낸 같은 양의 묶음",6,1,1,"","decimalContextMul",1000,"decimalMul","한 묶음의 양과 묶음 수로 전체 양을 구한다."),new Catalog.Skill(DIV,"소수로 나타낸 양을 똑같이 나누기",6,1,1,"","decimalContextDiv",1000,"decimalDivInt","전체 양을 같은 수의 묶음으로 나눈다."));
 public static boolean supports(String id){return MUL.equals(id)||DIV.equals(id);}
 public record Givens(String raw,int groups,String unit,boolean multiply){}
 public static Givens read(Question q){if(q==null||!supports(q.skillId)||q.prompt==null)return null;boolean mul=MUL.equals(q.skillId);String n="(\\d{1,2}\\.\\d{1,3})",count="(\\d{1,2})";for(String unit:List.of("m","L","kg")){String pattern=mul?(unit.equals("m")?n+" m인 끈 "+count+"개를 겹치지 않게 잇습니다.\\n이어진 끈의 길이는 몇 m인가요\\?":unit.equals("L")?"물 "+n+" L가 든 병 "+count+"개가 있습니다.\\n물은 모두 몇 L인가요\\?":"쌀 "+n+" kg이 든 봉지 "+count+"개가 있습니다.\\n쌀은 모두 몇 kg인가요\\?"):(unit.equals("m")?"끈 "+n+" m를 길이가 같은 "+count+"조각으로 나눕니다.\\n한 조각은 몇 m인가요\\?":unit.equals("L")?"물 "+n+" L를 "+count+"병에 똑같이 나눕니다.\\n한 병에는 몇 L가 들어가나요\\?":"쌀 "+n+" kg을 "+count+"봉지에 똑같이 나눕니다.\\n한 봉지에는 몇 kg이 들어가나요\\?");Matcher m=Pattern.compile(pattern).matcher(q.prompt);if(m.matches()){int k=Integer.parseInt(m.group(2));if(k<1)return null;return new Givens(m.group(1),k,unit,mul);}}return null;}
 public static Question arithmetic(Question q){Givens v=read(q);return v==null?null:v.multiply?DecimalWholeProducts.make(v.raw,v.groups):DecimalWholeQuotients.make(v.raw,v.groups);}
 public static Question make(String id,String raw,int groups,String unit){if(!supports(id)||!Set.of("m","L","kg").contains(unit)||groups<1||groups>99)throw new IllegalArgumentException("Selected quantity group scope");boolean mul=MUL.equals(id);String prompt=mul?(unit.equals("m")?raw+" m인 끈 "+groups+"개를 겹치지 않게 잇습니다.\n이어진 끈의 길이는 몇 m인가요?":unit.equals("L")?"물 "+raw+" L가 든 병 "+groups+"개가 있습니다.\n물은 모두 몇 L인가요?":"쌀 "+raw+" kg이 든 봉지 "+groups+"개가 있습니다.\n쌀은 모두 몇 kg인가요?"):(unit.equals("m")?"끈 "+raw+" m를 길이가 같은 "+groups+"조각으로 나눕니다.\n한 조각은 몇 m인가요?":unit.equals("L")?"물 "+raw+" L를 "+groups+"병에 똑같이 나눕니다.\n한 병에는 몇 L가 들어가나요?":"쌀 "+raw+" kg을 "+groups+"봉지에 똑같이 나눕니다.\n한 봉지에는 몇 kg이 들어가나요?");Question q=new Question(id,prompt,"","0"),calc=arithmetic(q);if(calc==null)throw new IllegalArgumentException("Selected quantity group givens");q.answers=calc.answers.clone();q.answerFormat=calc.answerFormat;q.decimal=true;q.stepSupport=false;attach(q);return q;}
 static Question create(Catalog.Skill s,Random random,CurriculumLimits l){int max=l.wholeMaximum(99),places=l.decimalPlaces(3);if(max<0||max>99||places<1||places>3)throw new IllegalArgumentException("Selected quantity group supply");int precision=1+random.nextInt(places);String raw=BigDecimal.valueOf(random.nextInt((max+1)*(int)Math.pow(10,precision)),precision).toPlainString();return make(s.id,raw,1+random.nextInt(99),List.of("m","L","kg").get(random.nextInt(3)));}
 static Checker.Result check(Question q,List<String> answers){Question calc=arithmetic(q);if(calc==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"문제의 양 확인 필요");return MUL.equals(q.skillId)?DecimalWholeProducts.check(calc,answers):DecimalWholeQuotients.check(calc,answers);}
 public static int errorPart(Question q,String raw){Givens v=read(q);if(v==null||v.multiply||FractionInput.invalidPart(raw)!=0)return 0;Rational expected=Expression.number(v.raw).div(Rational.of(v.groups));String[] pair=FractionInput.parts(raw);BigInteger n=new BigInteger(pair[0]),d=new BigInteger(pair[1]);if(n.multiply(expected.d).equals(expected.n.multiply(d)))return 0;if(d.equals(expected.d))return 1;if(n.equals(expected.n))return 2;return 0;}
 public static void attach(Question q){Question calc=arithmetic(q);if(calc==null)return;StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="decimal-measure-groups-v1";Map<String,String> choices=new LinkedHashMap<>();choices.put("mul","전체 양 = 한 묶음의 양 × 묶음 수");choices.put("div","한 묶음의 양 = 전체 양 ÷ 묶음 수");h.choice("문장에서 구하는 양에 맞는 관계를 고르세요.",choices,MUL.equals(q.skillId)?"mul":"div");h.frames.addAll(calc.studyGuide.frames);h.frames.get(1).instruction="문제의 양을 쓰세요.";h.frames.get(2).instruction="묶음 수를 쓰세요.";if(calc.studyGuide.resultNumeratorFrame!=null)h.fractionResult(calc.studyGuide.resultNumeratorFrame+1,calc.studyGuide.resultDenominatorFrame+1);q.studyGuide=h;}
}
